SELECT COMMONID||'_'||CITEMID AS VALUE_COL, CODENAME AS TEXT_COL FROM SYSCOMMITEM WHERE 1=1
AND COMMONID = #{CODE1}
AND COMMONID = #{PARAM}
ORDER BY SORTORDER

SELECT COMMONID||'_'||CITEMID AS VALUE_COL, CODENAME AS TEXT_COL FROM SYSCOMMITEM WHERE 1=1
AND COMMONID = #{CODE1}
ORDER BY SORTORDER

SELECT COMMONID||'_'||CITEMID AS VALUE_COL, CODENAME AS TEXT_COL FROM SYSCOMMITEM WHERE 1=1
AND COMMONID = #{PARAM}
ORDER BY SORTORDER

SELECT F.UUID, F.UUID AS ATTACH, F.GUUID, F.RPATH, F.PATH, F.FNAME, F.NAME AS UUID_FILEVIEW, F.NAME AS ATTACH_FILEVIEW, F.MIME, F.STYPE, F.BYTE, F.CREATEUSER, F.CREATEDATE, F.UPDATEUSER, F.UPDATEDATE, F.DELETEYN, CASE WHEN F.BYTE < 1024 THEN F.BYTE || ' BYTE' WHEN F.BYTE > 1024 AND F.BYTE < (1024*1024) THEN ROUND(F.BYTE/1024,2) || ' KB' ELSE ROUND(F.BYTE/(1024*1024),2) || ' MB' END AS BYTE_FILESIZEVIEW, 'Y' AS UPTBYN FROM SYSFILE F WHERE 1=1
AND F.GUUID = #{GUUID}
AND F.DELETEYN = #{DELETEYN}

SELECT A.SEQ , A.UUID , A.SHORTX , A.UUID AS ATTACH , B.RPATH , B.PATH , B.FNAME , B.NAME AS UUID_FILEVIEW , B.NAME AS ATTACH_FILEVIEW , B.MIME , B.STYPE , CASE WHEN B.BYTE < 1024 THEN B.BYTE || ' BYTE' WHEN B.BYTE > 1024 AND B.BYTE < (1024*1024) THEN ROUND(B.BYTE/1024,2) || ' KB' ELSE ROUND(B.BYTE/(1024*1024),2) || ' MB' END AS BYTE_FILESIZEVIEW , A.CREATEUSER , A.CREATEDATE , A.UPDATEUSER , A.UPDATEDATE FROM SYSFILEDEMO A LEFT OUTER JOIN SYSFILE B ON A.UUID = B.UUID WHERE 1=1
${RANGE_SQL}
ORDER BY A.SEQ DESC

mapper.update:
UPDATE SYSFILEDEMO
SET    UUID = #{ATTACH}
  ,    SHORTX = NVL(#{SHORTX},' ')
  ,    UPDATEUSER = #{SES_USER_ID}
  ,    UPDATEDATE = SYSDATE
WHERE  SEQ = #{SEQ}

